function managerList(){const panel=$('recon-detail');$('recon-follow').append(panel);const filters=document.querySelector('.recon-filters');filters.classList.add('manager-floating-menu');document.querySelectorAll('[data-status]').forEach(b=>{const id=b.dataset.status,count=state.reports.filter(r=>r.status===id).length;b.setAttribute('aria-pressed',String(id===status));b.innerHTML='<span>'+({pending:'Pendientes',returned:'Devueltos',confirmed:'Histórico'}[id])+'</span><b class="manager-menu-count '+(id==='pending'&&count?'has-pending':'')+'">'+count+'</b>';});if(!filters.querySelector('[data-action="refresh"]'))filters.insertAdjacentHTML('beforeend',action(reconIcon('refresh')+'<span>Actualizar</span>','refresh','manager-menu-refresh'));const reports=state.reports.filter(r=>r.status===status).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));$('recon-history-title').textContent=({pending:'Listos para revisar',returned:'En espera de corrección',confirmed:'Cuadres confirmados'}[status]);$('recon-list').innerHTML=reports.map(r=>'<button type="button" class="recon-history-card manager-inbox-card" data-history-id="'+esc(r.id)+'" data-report="'+esc(r.id)+'" aria-controls="recon-detail"><span class="manager-card-content"><span class="manager-card-icon">'+reconIcon('clipboard')+'</span><span><span class="manager-card-title"><strong class="manager-card-number">Cuadre #'+String(r.number).padStart(3,'0')+'</strong><span class="recon-history-state">'+esc({pending:'Pendiente',returned:'Devuelto',confirmed:'Confirmado'}[r.status])+'</span></span><span class="manager-card-person">'+esc(r.created_by_name)+'</span><span class="recon-history-meta">'+esc(when(r.created_at))+'</span></span></span></button>').join('')||'<div class="recon-history-empty">'+reconIcon('clipboard')+'<h3>'+({pending:'No tienes cuadres pendientes',returned:'No hay cuadres devueltos',confirmed:'Aún no hay cuadres confirmados'}[status])+'</h3></div>';managerView(!!current);}
