function recoveredSupplies(s){const f=s.cost_settlement,products=(f.products||[]).filter(p=>Number(p.recovered)>0),qty=n=>Number(n||0).toLocaleString('es-ES',{maximumFractionDigits:6}),sum=products.reduce((n,p)=>n+Number(p.recovered||0),0),adjustment=Math.round((Number(f.reserve||0)-sum)*100)/100;return table(['Producto / servicio','Cantidad','Recuperado en este cuadre'],products.map(p=>'<tr><td>'+esc(p.name)+'</td><td>'+qty(p.quantity)+'</td><td>'+budgetMoney(p.recovered)+'</td></tr>').concat(adjustment?['<tr><td>Ajuste de centavos</td><td>—</td><td>'+budgetMoney(adjustment)+'</td></tr>']:[]));}
